PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY NOT NULL, telegram_id TEXT NOT NULL UNIQUE, first_name TEXT NOT NULL, last_name TEXT, username TEXT, avatar_url TEXT, age INTEGER, gender TEXT, height_cm REAL, current_weight_kg REAL, target_weight_kg REAL, activity_level TEXT, goal TEXT, calorie_target INTEGER NOT NULL DEFAULT 2000, protein_target INTEGER NOT NULL DEFAULT 120, carbs_target INTEGER NOT NULL DEFAULT 220, fat_target INTEGER NOT NULL DEFAULT 65, water_target_ml INTEGER NOT NULL DEFAULT 2200, onboarding_complete INTEGER NOT NULL DEFAULT 0, xp INTEGER NOT NULL DEFAULT 0, level INTEGER NOT NULL DEFAULT 1, coins INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX users_telegram_idx ON users(telegram_id);
CREATE TABLE foods (id TEXT PRIMARY KEY NOT NULL, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, brand TEXT, serving_label TEXT NOT NULL DEFAULT '1 serving', serving_grams REAL NOT NULL DEFAULT 100, calories REAL NOT NULL, protein REAL NOT NULL DEFAULT 0, carbs REAL NOT NULL DEFAULT 0, fat REAL NOT NULL DEFAULT 0, is_favorite INTEGER NOT NULL DEFAULT 0, use_count INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX foods_name_idx ON foods(name); CREATE INDEX foods_user_idx ON foods(user_id);
CREATE TABLE meals (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, meal_type TEXT NOT NULL, name TEXT, logged_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL); CREATE INDEX meals_user_date_idx ON meals(user_id, logged_at);
CREATE TABLE meal_items (id TEXT PRIMARY KEY NOT NULL, meal_id TEXT NOT NULL REFERENCES meals(id) ON DELETE CASCADE, food_id TEXT REFERENCES foods(id) ON DELETE SET NULL, food_name TEXT NOT NULL, serving_label TEXT NOT NULL, multiplier REAL NOT NULL DEFAULT 1, calories REAL NOT NULL, protein REAL NOT NULL, carbs REAL NOT NULL, fat REAL NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL); CREATE INDEX meal_items_meal_idx ON meal_items(meal_id);
CREATE TABLE water_logs (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, amount_ml INTEGER NOT NULL, logged_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL); CREATE INDEX water_user_date_idx ON water_logs(user_id, logged_at);
CREATE TABLE weight_logs (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, weight_kg REAL NOT NULL, logged_at TEXT NOT NULL, note TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL); CREATE INDEX weight_user_date_idx ON weight_logs(user_id, logged_at);
CREATE TABLE daily_progress (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, date TEXT NOT NULL, calories REAL NOT NULL DEFAULT 0, protein REAL NOT NULL DEFAULT 0, carbs REAL NOT NULL DEFAULT 0, fat REAL NOT NULL DEFAULT 0, water_ml INTEGER NOT NULL DEFAULT 0, meals_logged INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL); CREATE UNIQUE INDEX daily_progress_user_date_unique ON daily_progress(user_id, date);
CREATE TABLE missions (id TEXT PRIMARY KEY NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, icon TEXT NOT NULL, metric TEXT NOT NULL, target REAL NOT NULL, xp_reward INTEGER NOT NULL, coin_reward INTEGER NOT NULL DEFAULT 5, period TEXT NOT NULL DEFAULT 'daily', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE completed_missions (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, mission_id TEXT NOT NULL REFERENCES missions(id) ON DELETE CASCADE, period_key TEXT NOT NULL, progress REAL NOT NULL DEFAULT 0, completed_at TEXT, claimed_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL); CREATE UNIQUE INDEX completed_mission_period_unique ON completed_missions(user_id, mission_id, period_key);
CREATE TABLE achievements (id TEXT PRIMARY KEY NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, icon TEXT NOT NULL, metric TEXT NOT NULL, target REAL NOT NULL, xp_reward INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE user_achievements (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, achievement_id TEXT NOT NULL REFERENCES achievements(id) ON DELETE CASCADE, unlocked_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL); CREATE UNIQUE INDEX user_achievement_unique ON user_achievements(user_id, achievement_id);
CREATE TABLE xp_logs (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, amount INTEGER NOT NULL, reason TEXT NOT NULL, reference_id TEXT, created_at TEXT NOT NULL); CREATE INDEX xp_user_idx ON xp_logs(user_id);
CREATE TABLE streaks (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, current_streak INTEGER NOT NULL DEFAULT 0, longest_streak INTEGER NOT NULL DEFAULT 0, last_active_date TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE settings (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, theme TEXT NOT NULL DEFAULT 'system', language TEXT NOT NULL DEFAULT 'en', units TEXT NOT NULL DEFAULT 'metric', daily_reminder INTEGER NOT NULL DEFAULT 1, water_reminder INTEGER NOT NULL DEFAULT 1, calorie_reminder INTEGER NOT NULL DEFAULT 1, streak_warning INTEGER NOT NULL DEFAULT 1, reminder_hour INTEGER NOT NULL DEFAULT 9, timezone TEXT NOT NULL DEFAULT 'UTC', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE sessions (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, created_at TEXT NOT NULL); CREATE INDEX sessions_user_idx ON sessions(user_id);
